// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;

    function setUp() public { c = new DEP_BANK(); }

    function testFuzz_property(uint256 amount, uint256 minSum) public {
        amount = bound(amount, 1, 1e30);
        minSum = bound(minSum, 0, 1e30);

        c.SetMinSum(minSum);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        FailingCallee bad = new FailingCallee();
        vm.deal(address(bad), amount);

        vm.prank(address(bad));
        c.Deposit{value: amount}();

        uint256 beforeBal = c.balances(address(bad));
        if (beforeBal < c.MinSum() || beforeBal < amount) return;

        vm.prank(address(bad));
        (bool ok,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", beforeBal));

        if (!ok) {
            assertTrue(c.balances(address(bad)) == beforeBal);
        } else {
            assertTrue(c.balances(address(bad)) == beforeBal);
        }
    }
}

contract LogFile {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

contract FailingCallee {
    receive() external payable { revert(); }
    fallback() external payable { revert(); }
}
